from fastapi import FastAPI, Depends, Response
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

def modify_response():
    return Response(content="modified", media_type="text/plain")

@app.get("/")
def endpoint(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "hello"}

@app.get("/alt")
def endpoint_alt(response: Response = Depends(modify_response)):
    return {"message": "hello"}

@app.get("/reg")
def endpoint_reg(response: Response):
    return {"message": "hello"}

client = TestClient(app)

def test_response_dependency():
    # Test Annotated[Response, Depends(...)]
    # Note: The actual behavior of the endpoint return value might be affected 
    # by how FastAPI handles the Response object returned by the dependency.
    # But the main goal is that it doesn't raise AssertionError during startup/call.
    res = client.get("/")
    assert res.status_code == 200

    # Test Response = Depends(...)
    res = client.get("/alt")
    assert res.status_code == 200

    # Test regular Response injection
    res = client.get("/reg")
    assert res.status_code == 200

if __name__ == "__main__":
    try:
        test_response_dependency()
        print("Tests passed!")
    except Exception as e:
        print(f"Tests failed: {e}")
        raise e
